class ErlangDistribution(SingleContinuousDistribution):
    # Erlang distribution is a special case of the Gamma distribution.
    # CDF is the generalized lower incomplete gamma function, G(a, x) = gamma(a, x) / Gamma(a)

    def __init__(self, a, scale=1):
        self.a = a
        self.scale = scale
        super().__init__(a, scale)

    def pdf(self, x, *, a, scale=1, **kwargs):
        from sympy import gamma, exp, oo
        if x.is_real and x > 0:
            return (a * (a*x/scale)**(a - 1) * exp(-a*x/scale)) / (scale * gamma(a))
        else:
            return 0

    def _cdf(self, x, a, scale=1, **kwargs):
      from sympy import lowergamma, gamma, oo
      return lowergamma(a, x/scale)/gamma(a)

class LaplaceDistribution(SingleContinuousDistribution):
    # Laplace distribution
    # Wikipedia:
    # 'The cumulative distribution function (CDF) is
    # F(x; mu, b) = 1/2 + 1/2 * sign(x - mu) * (1 - exp(-abs(x - mu)/b))
    # This can be written piecewise as:
    # F(x; mu, b) = (1 - exp((mu - x)/b))/2 for x < mu
    # F(x; mu, b) = (1 - exp(-(x - mu)/b))/2 for x >= mu

    def __init__(self, mu=0, b=1):
        self.b = b
        super().__init__(mu, b)

    def pdf(self, x, mu=0, b=1,*args,**kwargs):
        from sympy import exp, sign, oo
        return (1/(2*b)) * exp(-abs(x - mu)/b)

    def _cdf(self, x, mu=0, b=1,*args,**kwargs):
        from sympy import exp, sign, oo
        return (1/2) + (sign(x - mu)/2) * (1 - exp(-abs(x - mu)/b))

class LogisticDistribution(SingleContinuousDistribution):
    # Logistic distribution
    # Wikipedia:
    # CDF: 1/(1 + exp(- (x-mu)/s ))

    def __init__(self, mu=0, s=1):
        self.s = s
        super().__init__(mu, s)

    def pdf(self, x, mu=0, s=1):
        from sympy import exp, oo
        return (1/s) * exp(-(x-mu)/s) / (1 + exp(-(x-mu)/s))**2

    def _cdf(self, x, mu=0, s=1):
        from sympy import exp, oo
        return 1/(1 + exp(-(x-mu)/s))
